package main

import (
	"encoding/xml"
	"fmt"
	"os"
	"strings"
)

func main(){
	data, _ := os.ReadFile("assets/test.wsdl")
	decoder := xml.NewDecoder(strings.NewReader(string(data)))
	for {
		tok, err := decoder.Token()
		if err != nil {
			break
		}
		if se, ok := tok.(xml.StartElement); ok {
			fmt.Printf("Start %q Space %q Local %q Attrs %v\n", se.Name, se.Name.Space, se.Name.Local, se.Attr)
		}
	}

	// Test with stock.wsdl which uses default namespace for schema (xmlns="http://www.w3.org/2001/XMLSchema") not prefix s:
	// That case our earlier struct used `s:` prefix; but stock uses unprefixed with xmlns default.
	// Let's do generic: we need to handle both <s:element> with prefix s and <element> with default ns.
	// So we need to check Local names only.
	// We'll try parsing with custom handling: look at Local == "element" irrespective of Space.
	// To do that we need to handle raw XML via decoder token iteration.
}
EOF
go run /tmp/xmltest2.go 2>&1 | head -n 100
"}

