	Pattern string `xml:"pattern,attr"`
	MinLength *XSDMinLength `xml:"minLength"`
	Annotation *XSDAnnotation `xml:"annotation"`
}

type XSDEnumeration struct {
	Value string `xml:"value,attr"`
	Annotation *XSDAnnotation `xml:"annotation"`
}

type XSDMinLength struct {
	Value string `xml:"value,attr"`
}

type XSDList struct {
	ItemType string `xml:"itemType,attr"`
}

type XSDUnion struct {
	MemberTypes string `xml:"memberTypes,attr"`
}

type XSDImport struct {
	Namespace string `xml:"namespace,attr"`
	SchemaLocation string `xml:"schemaLocation,attr"`
}

type XSDSimpleContent struct {
	Extension *XSDExtension `xml:"extension"`
	Restriction *XSDRestriction `xml:"restriction"`
}

type XSDComplexContent struct {
	Extension *XSDExtension `xml:"extension"`
	Restriction *XSDRestriction `xml:"restriction"`
}

type XSDExtension struct {
	Base string `xml:"base,attr"`
	Attributes []XSDAttribute `xml:"attribute"`
	Sequence *XSDSequence `xml:"sequence"`
	Choice *XSDChoice `xml:"choice"`
}

type XSDAnnotation struct {
	Documentation string `xml:"documentation"`
}

func main(){
	xmlStr := `<?xml version="1.0" encoding="utf-8"?>
<wsdl:definitions xmlns:s="http://www.w3.org/2001/XMLSchema" xmlns:tns="http://www.mnb.hu/webservices/" xmlns:soap="http://schemas.xmlsoap.org/wsdl/soap/" xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/" targetNamespace="http://www.mnb.hu/webservices/">
  <wsdl:types>
    <s:schema elementFormDefault="qualified" targetNamespace="http://www.mnb.hu/webservices/">
      <s:element name="GetInfo">
        <s:complexType>
          <s:sequence>
            <s:element name="Id">
              <s:annotation><s:documentation>comment</s:documentation></s:annotation>
              <s:simpleType><s:restriction base="s:string"><s:minLength value="2"/></s:restriction></s:simpleType>
            </s:element>
          </s:sequence>
        </s:complexType>
      </s:element>
      <s:complexType name="ResponseStatus">
        <s:sequence>
          <s:element name="status" minOccurs="0" maxOccurs="unbounded">
            <s:complexType>
              <s:simpleContent>
                <s:extension base="s:string">
                  <s:attribute name="code" use="required"><s:simpleType><s:restriction base="s:string"><s:enumeration value="UnrecognizedTrimName"/></s:restriction></s:simpleType></s:attribute>
                </s:extension>
              </s:simpleContent>
            </s:complexType>
          </s:element>
        </s:sequence>
        <s:attribute ref="tns:responseCode"/>
      </s:complexType>
    </s:schema>
  </wsdl:types>
</wsdl:definitions>`
	decoder := xml.NewDecoder(strings.NewReader(xmlStr))
	// Need to handle prefix?
	// Encoding/xml handles namespace via local and space, but struct tags use local names via xml:"..." with local matching.
	// For testing, we'll try Unmarshal
	var w WSDL
	if err := xml.Unmarshal([]byte(xmlStr), &w); err != nil {
		fmt.Println("unmarshal err", err)
		return
	}
	fmt.Printf("WSDL %+v\n", w)
	fmt.Printf("Types schemas %d\n", len(w.Types.Schemas))
	for i, s := range w.Types.Schemas {
		fmt.Printf(" schema %d ns=%q elements=%d complexTypes=%d\n", i, s.TargetNamespace, len(s.Elements), len(s.ComplexTypes))
		for _, e := range s.Elements {
			fmt.Printf("  element %q type=%q\n", e.Name, e.Type)
			if e.ComplexType != nil {
				fmt.Printf("   complexType present\n")
				if e.ComplexType.Sequence != nil {
					fmt.Printf("    sequence elements %d\n", len(e.ComplexType.Sequence.Elements))
					for _, ce := range e.ComplexType.Sequence.Elements {
						fmt.Printf("      seq elem %q type %q simpleType bool %v\n", ce.Name, ce.Type, ce.SimpleType != nil)
						if ce.SimpleType != nil && ce.SimpleType.Restriction != nil {
							fmt.Printf("        restriction base %q\n", ce.SimpleType.Restriction.Base)
						}
					}
				}
			}
		}
		for _, ct := range s.ComplexTypes {
			fmt.Printf("  complexType %q\n", ct.Name)
			if ct.Sequence != nil {
				fmt.Printf("   sequence %d\n", len(ct.Sequence.Elements))
			}
			if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
				fmt.Printf("   simpleContent extension base %q attrs %d\n", ct.SimpleContent.Extension.Base, len(ct.SimpleContent.Extension.Attributes))
			}
		}
	}
	_ = decoder
}
EOF
go run /tmp/goxml.go
"}

