	insecureFlag = flag.Bool("i", false, "Skips TLS Verification")
	versionFlag  = flag.Bool("v", false, "Shows gowsdl version")
	makePublicFlag = flag.Bool("make-public", true, "Make the generated types public/exported (default true)")
)

func printUsage() {
	fmt.Fprintf(os.Stderr, "Usage: %s [options] myservice.wsdl\n", os.Args[0])
	flag.PrintDefaults()
}

func main() {
	flag.Usage = printUsage
	flag.CommandLine.SetOutput(os.Stderr)
	// flag parsing with ContinueOnError already set by default? Need to handle errors
	err := flag.CommandLine.Parse(os.Args[1:])
	if err != nil {
		// flag package already printed error to stderr
		if err == flag.ErrHelp {
			os.Exit(0)
		}
		// For other errors, flag already printed usage? But we need to ensure usage printed.
		// flag package with ContinueOnError prints error and usage? Actually it prints error then usage via PrintDefaults? Our custom Usage prints usage.
