func parseWSDL(data []byte, baseDir string, insecure bool) (*WSDL, []*XSDSchema, error) {
	var wsdl WSDL
	// Need to handle namespace prefixes: encoding/xml matches local name only, so we can use generic decoder that strips namespaces?
	// Use a custom approach: replace xmlns prefixes with empty? Simpler: use Decoder with Token and handle?
	// But we can try Unmarshal directly as we did earlier; it worked for test.wsdl
	if err := xml.Unmarshal(data, &wsdl); err != nil {
		return nil, nil, err
	}
	// Collect schemas
	var schemas []*XSDSchema
	for i := range wsdl.Types.Schemas {
		schemas = append(schemas, &wsdl.Types.Schemas[i])
		// Handle imports
		for _, imp := range wsdl.Types.Schemas[i].Imports {
			if imp.SchemaLocation == "" {
				continue
			}
			loc := imp.SchemaLocation
			var absLoc string
			var content []byte
			var err error
			if strings.HasPrefix(loc, "http://") || strings.HasPrefix(loc, "https://") {
				absLoc = loc
				fmt.Printf("🍀  Reading file %s\n", absLoc)
				// fetch
				client := &http.Client{}
				if insecure {
					client.Transport = &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}}
				}
				resp, e := client.Get(loc)
				if e != nil {
					return nil, nil, fmt.Errorf("open %s: %v", loc, e)
				}
				content, e = io.ReadAll(resp.Body)
				resp.Body.Close()
				if e != nil {
					return nil, nil, fmt.Errorf("open %s: %v", loc, e)
				}
			} else {
				// relative path
				absLoc = filepath.Join(baseDir, loc)
				absLoc2, _ := filepath.Abs(absLoc)
				absLoc = absLoc2
				fmt.Printf("🍀  Reading file %s\n", absLoc)
				content, err = os.ReadFile(absLoc)
				if err != nil {
					return nil, nil, err
				}
			}
			// Try to parse this imported schema as standalone schema (not wsdl)
			// It may be an XSD file with <schema> root, not <definitions>
			// Try to unmarshal as XSDSchema
			var sch XSDSchema
			if err := xml.Unmarshal(content, &sch); err != nil {
				// maybe it's WSDL import? ignore
				continue
			}
			schemas = append(schemas, &sch)
		}
		// Handle includes similarly
		for _, inc := range wsdl.Types.Schemas[i].Includes {
			if inc.SchemaLocation == "" {
				continue
			}
			loc := inc.SchemaLocation
			absLoc := filepath.Join(baseDir, loc)
			absLoc2, _ := filepath.Abs(absLoc)
			absLoc = absLoc2
			fmt.Printf("🍀  Reading file %s\n", absLoc)
			content, err := os.ReadFile(absLoc)
			if err != nil {
				return nil, nil, err
			}
			var sch XSDSchema
			if err := xml.Unmarshal(content, &sch); err != nil {
				continue
			}
			schemas = append(schemas, &sch)
		}
	}
	// Also handle wsdl:import
	for _, imp := range wsdl.Imports {
		if imp.Location == "" {
			continue
		}
		loc := imp.Location
		var absLoc string
		var content []byte
		if strings.HasPrefix(loc, "http://") || strings.HasPrefix(loc, "https://") {
			absLoc = loc
			fmt.Printf("🍀  Reading file %s\n", absLoc)
			client := &http.Client{}
			if insecure {
				client.Transport = &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}}
			}
			resp, e := client.Get(loc)
			if e != nil {
				return nil, nil, fmt.Errorf("open %s: %v", loc, e)
			}
			content, _ = io.ReadAll(resp.Body)
			resp.Body.Close()
		} else {
			absLoc = filepath.Join(baseDir, loc)
			absLoc2, _ := filepath.Abs(absLoc)
			absLoc = absLoc2
			fmt.Printf("🍀  Reading file %s\n", absLoc)
			var e error
			content, e = os.ReadFile(absLoc)
			if e != nil {
				return nil, nil, e
			}
		}
		// Parse imported WSDL recursively and merge its schemas/messages etc.
		impWsdl, impSchemas, e := parseWSDL(content, filepath.Dir(absLoc), insecure)
		if e != nil {
			continue
		}
		// Merge
		wsdl.Messages = append(wsdl.Messages, impWsdl.Messages...)
		wsdl.PortTypes = append(wsdl.PortTypes, impWsdl.PortTypes...)
		wsdl.Bindings = append(wsdl.Bindings, impWsdl.Bindings...)
		wsdl.Services = append(wsdl.Services, impWsdl.Services...)
		schemas = append(schemas, impSchemas...)
	}
	return &wsdl, schemas, nil
}

