		os.Exit(0)
	}

	if flag.NArg() == 0 {
		printUsage()
		os.Exit(0)
	}

	wsdlPath := flag.Arg(0)
	absWsdl, err := filepath.Abs(wsdlPath)
	if err != nil {
		absWsdl = wsdlPath
	}
	fmt.Printf("🍀  Reading file %s\n", absWsdl)

	data, err := readFileOrURL(wsdlPath, *insecureFlag, absWsdl)
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	// Need to handle external schema imports recursively
	// For now, try to resolve imports inside WSDL
	// We'll parse and if there are imports with schemaLocation, try to read them
	// If any fails, print error and exit 1 (as original does for EPCglobal)
	// This is done inside parse step, but we also need to print Reading file for each import
	// For simplicity, we will scan raw XML for schemaLocation and attempt to read
	// If import file not found, print error as original does: "open <abs>: no such file or directory"
	// Original for EPCglobal: it printed Reading file for wsdl, then Reading file for EPCglobal.xsd, then open error

	// We'll attempt to handle imports by parsing WSDL struct and looking at schemas
	wsdl, schemas, err := parseWSDL(data, filepath.Dir(absWsdl), *insecureFlag)
	if err != nil {
		// parse error? But original would just generate with maybe warnings?
		// For now, print error and exit 1?
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	// Generate
	packageDir := filepath.Join(*dirFlag, *pkgFlag)
	// Try to create package directory (like os.Mkdir with 0744)
	// Use Mkdir, not MkdirAll, to match original behavior where parent must exist
	// But we need to handle case where packageDir already exists -> ignore error
	// Also need to handle nested package like a/b where a exists but b not -> Mkdir will create b, but if a doesn't exist, Mkdir fails
	// Original seems to use Mkdir with 0744, not MkdirAll, as we observed.
	// Let's try Mkdir
	if err := os.Mkdir(packageDir, 0744); err != nil && !os.IsExist(err) {
		// If Mkdir fails because parent doesn't exist, we still try to continue? But original would then fail on file create with "no such file or directory"
		// So we just ignore Mkdir error and proceed to file creation which will fail appropriately
	}

	clientPath := filepath.Join(packageDir, *fileFlag)
	serverPath := filepath.Join(packageDir, "server"+*fileFlag)

	// Ensure parent dirs for client/server files? No, original fails if parent of o doesn't exist.
	// So we just try to create files; if parent missing, Create will fail with "no such file or directory" which we should handle

	err = generateClient(clientPath, wsdl, schemas, *pkgFlag, *makePublicFlag, data)
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}
	err = generateServer(serverPath, wsdl, schemas, *pkgFlag, *makePublicFlag, data)
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("🍀  Done 👍\n")
}

func readFileOrURL(p, insecure bool, absPath string) ([]byte, error) {
	if strings.HasPrefix(p, "http://") || strings.HasPrefix(p, "https://") {
		// need to print Reading file for URL? Original prints same "Reading file http://..."
		// But we already printed for wsdlPath, for imports we will also print
		client := &http.Client{}
		if insecure {
			client.Transport = &http.Transport{
				TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
			}
		}
		resp, err := client.Get(p)
		if err != nil {
			return nil, fmt.Errorf("open %s: %v", p, err)
		}
		defer resp.Body.Close()
		return io.ReadAll(resp.Body)
	}
	// Local file
	// absPath already resolved
	b, err := os.ReadFile(absPath)
	if err != nil {
		// Return error formatted as "open <abs>: no such file or directory"
		// os.ReadFile error already is "open <abs>: no such file or directory"
		return nil, err
	}
	return b, nil
}

