func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

// Helper to handle makePublic for names
func publicName(name string, makePublic bool) string {
	if makePublic {
		return capitalizeFirst(name)
	}
	// For false, lower first
	return lowerFirst(name)
}

// XSD to Go type mapping
func xsdTypeToGo(xsd string, nillable bool, maxOccurs string) string {
	// Strip prefix
	local := xsd
	if idx := strings.LastIndex(xsd, ":"); idx != -1 {
		local = xsd[idx+1:]
	}
	// Trim namespace like {http://...}?
	// Also handle array types? Not needed
	goType := ""
	switch local {
	case "string":
		goType = "string"
	case "boolean":
		goType = "bool"
	case "decimal", "double":
		goType = "float64"
	case "float":
		goType = "float32"
	case "int", "integer":
		goType = "int32"
	case "long":
		goType = "int64"
	case "short":
		goType = "int16"
	case "byte":
		goType = "int8"
	case "unsignedLong":
		goType = "uint64"
	case "unsignedInt":
		goType = "uint32"
	case "unsignedShort":
		goType = "uint16"
	case "unsignedByte":
		goType = "byte"
	case "nonNegativeInteger":
		goType = "uint32"
	case "anyURI":
		goType = "AnyURI"
	case "anyType":
		goType = "AnyType"
	case "NCName", "QName", "NOTATION", "duration", "gYearMonth", "gYear", "gMonthDay", "gDay", "gMonth", "positiveInteger", "negativeInteger", "nonPositiveInteger":
		goType = capitalizeFirst(local)
		// These will be pointer types later if needed? For now, we will handle pointer wrapping outside
		// For primitive duration etc., original used *Duration (pointer)
		// We'll return pointer later based on nillable/maxOccurs
		// For now, return base name
		// But we need to decide if these are pointer by default?
		// In our earlier test, duration with nillable false still gave *Duration? Wait test for duration with minOccurs 0 and nillable nil gave *Duration? Actually we tested duration with minOccurs 0 and got *Duration (field1 *Duration) even without nillable.
		// Let's see: we had TestType with field1 type s:duration, minOccurs 0, nillable nil => Field1 *Duration (pointer). So duration etc. are pointer even without nillable.
		// So we need to handle: for those types, always pointer?
		// Let's check other types: gYearMonth etc. also pointer even without nillable.
		// So for these, we should return "*"+goType if not slice
		// But for our mapping, we can handle in caller
		// For now return goType without star, caller will add star if needed
		// We need to know which types are pointer types
		// Let's define set of pointer types
	case "hexBinary", "base64Binary":
		goType = "[]byte"
	case "dateTime":
		goType = "soap.XSDDateTime"
	case "date":
		goType = "soap.XSDDate"
	case "time":
		goType = "soap.XSDTime"
	case "ID", "IDREF", "NMTOKEN", "language", "normalizedString", "token":
		goType = "string"
	default:
		// Custom type: strip prefix and capitalize first
		// e.g., tns:ArrayOfWorkshop -> ArrayOfWorkshop
		goType = capitalizeFirst(local)
		// Also handle encoded like WSF_x0020_Schedule -> keep as is
	}
	// Handle nillable and maxOccurs for pointer/slice in caller, but for now we just return base
	// For slice, caller will wrap.
	return goType
}

func isPointerType(local string) bool {
	switch local {
	case "duration", "gYearMonth", "gYear", "gMonthDay", "gDay", "gMonth", "QName", "NOTATION", "positiveInteger", "negativeInteger", "nonPositiveInteger", "Duration", "GYearMonth", "GYear", "GMonthDay", "GDay", "GMonth", "PositiveInteger", "NegativeInteger", "NonPositiveInteger":
		return true
	}
	return false
}

func generateClient(path string, wsdl *WSDL, schemas []*XSDSchema, pkg string, makePublic bool, rawWsdl []byte) error {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	buf.WriteString(fmt.Sprintf("package %s\n\n", pkg))
