	buf.WriteString("var _ time.Time\n")
	buf.WriteString("var _ xml.Name\n\n")
	buf.WriteString("type AnyType struct {\n\tInnerXML string `xml:\",innerxml\"`\n}\n\n")
	buf.WriteString("type AnyURI string\n\n")
	buf.WriteString("type NCName string\n\n")

	// Collect types to generate
	// Use maps to avoid duplicate
	generated := make(map[string]bool)

	// Helper to generate struct for complex types etc.
	// For simplicity, we will iterate schemas in order and generate types as they appear
	// For each schema, process top-level elements, complexTypes, simpleTypes, attributes
	// Need to keep order as in WSDL file to match original output order
	// Original order for test.wsdl: GetInfo, GetInfoResponse, ElementWithLocalSimpleType, StartDate, ResponseStatus
	// That's order: elements GetInfo, GetInfoResponse, then complexType ResponseStatus, then attribute responseCode (but attribute not generated as type), then element elementWithLocalSimpleType, element startDate
	// Actually order in file: GetInfo element, GetInfoResponse element, complexType ResponseStatus, attribute responseCode, element elementWithLocalSimpleType, element startDate
	// Generated order: GetInfo, GetInfoResponse, ElementWithLocalSimpleType, StartDate, ResponseStatus
	// So ResponseStatus (complexType) appears after the two simple element types, even though in WSDL it was before them? Wait check: In test.wsdl, order is GetInfo, GetInfoResponse, ResponseStatus, responseCode attribute, elementWithLocalSimpleType, startDate . But generated order has ResponseStatus at end. So they reorder? Or they process elements first then complexTypes?

	// For now, we will just process in a simple order and try to match
	// Let's collect all top-level elements and types
	type genItem struct {
		kind string // "element", "complexType", "simpleType"
		name string
		obj interface{}
		schema *XSDSchema
		order int
	}
	var items []genItem
	order := 0
	for _, sch := range schemas {
		for i := range sch.Elements {
			el := &sch.Elements[i]
			items = append(items, genItem{kind: "element", name: el.Name, obj: el, schema: sch, order: order})
			order++
		}
		for i := range sch.ComplexTypes {
			ct := &sch.ComplexTypes[i]
			items = append(items, genItem{kind: "complexType", name: ct.Name, obj: ct, schema: sch, order: order})
			order++
		}
		for i := range sch.SimpleTypes {
			st := &sch.SimpleTypes[i]
			items = append(items, genItem{kind: "simpleType", name: st.Name, obj: st, schema: sch, order: order})
			order++
		}
		// Attributes are not generated as top-level types except as fields inside structs? The attribute responseCode is not generated as type
	}

	// Sort by order? Already in order, but we need to intermix? Original seems to intermix elements and complexTypes but not exactly.
	// For test.wsdl, our items order would be: GetInfo (element), GetInfoResponse (element), ResponseStatus (complexType), elementWithLocalSimpleType (element), startDate (element)
	// That's 5 items. Our order gives: 0:GetInfo,1:GetInfoResponse,2:ResponseStatus,3:elementWithLocalSimpleType,4:startDate . Generated order is 0,1,3,4,2 (ResponseStatus last). So they moved complexType to end.

	// Maybe they process elements first, then complexTypes, then simpleTypes?
	// Let's try separate: elements first in order, then complexTypes, then simpleTypes
	// For test, elements are GetInfo, GetInfoResponse, elementWithLocalSimpleType, startDate (4), complexTypes is ResponseStatus (1) => order would be GetInfo, GetInfoResponse, elementWithLocalSimpleType, startDate, ResponseStatus => matches generated! So they process elements first, then complexTypes.

	// Let's sort items: elements first, then simpleTypes?, then complexTypes? Check other wsdl like stock: elements TradePriceRequest, TradePrice (2 elements), no top-level complexTypes or simpleTypes? Actually stock's schema has two elements, no complexTypes. So order is just those two, which matches.

	// For mnb-exchange: elements GetInfo, GetInfoResponse, GetCurrentExchangeRates, GetCurrentExchangeRatesResponse, etc. (12 elements), no top-level complexTypes? Actually mnb has only elements, no top-level complexTypes? So order is just elements as they appear, which matches generated where GetInfo, GetInfoResponse, etc. in order as in WSDL.

	// For chromedata: it has many complexTypes and elements? Let's see order: In chromedata wsdl, there are many complexTypes like DriveTrain, Switch, etc., and elements like VersionInfo, etc. Hard to know.

	// Simplify: sort items by kind priority: element (0), simpleType (1), complexType (2) but keep original order within kind.

	// For test, simpleTypes top-level is none (ElementWithLocalSimpleType's simpleType is inline, not top-level). So order would be elements (GetInfo, GetInfoResponse, elementWithLocalSimpleType, startDate) then complexTypes (ResponseStatus) => matches.

	// Implement that sorting
	// We'll rebuild items sorted
	var elements []genItem
	var simpleTypes []genItem
	var complexTypes []genItem
	for _, it := range items {
		switch it.kind {
		case "element":
			elements = append(elements, it)
		case "simpleType":
			simpleTypes = append(simpleTypes, it)
		case "complexType":
			complexTypes = append(complexTypes, it)
		}
	}
	// Now process in order elements, simpleTypes, complexTypes
	sorted := append(elements, simpleTypes...)
	sorted = append(sorted, complexTypes...)

	for _, it := range sorted {
		switch it.kind {
		case "element":
			el := it.obj.(*XSDElement)
			// Skip if element has ref? Not top-level?
			generateElement(&buf, el, it.schema, makePublic, generated, schemas)
		case "complexType":
			ct := it.obj.(*XSDComplexType)
			generateComplexType(&buf, ct, it.schema, makePublic, generated, schemas)
		case "simpleType":
			st := it.obj.(*XSDSimpleType)
			generateSimpleType(&buf, st, it.schema, makePublic, generated)
		}
	}

	// Generate services
	// For each portType, generate interface and struct
	for _, pt := range wsdl.PortTypes {
		// Need to find binding for this portType to get soapActions
		// Find binding where Type is tns:PortTypeName
		// Also need messages
		generateService(&buf, &pt, wsdl, schemas, makePublic)
	}

	// Also need to handle case where there are no portTypes? Then no service interface

	// Format
	src := buf.Bytes()
	formatted, err := format.Source(src)
	if err != nil {
		// Original would print error: e.g., "4:10: expected ';', found '/'"
		// And still write unformatted file? Let's see: when formatting fails, original prints error and still creates file? For a/b case, file was created even though formatting failed. So we should write unformatted file in that case, and print error message?
		// The error message should be printed to stdout with emoji? Let's check for a/b case: error printed was "4:10: expected ';', found '/'" without emoji? Need to decide.
		// For now, we will write unformatted file and return error to be printed by caller
		// But we need to ensure file is written even when formatting fails
		// Write unformatted
		if err := os.WriteFile(path, src, 0644); err != nil {
			return err
		}
		return fmt.Errorf("%v", err)
	}
	if err := os.WriteFile(path, formatted, 0644); err != nil {
		return err
	}
	return nil
}

func generateElement(buf *bytes.Buffer, el *XSDElement, schema *XSDSchema, makePublic bool, generated map[string]bool, schemas []*XSDSchema) {
	name := el.Name
	if name == "" {
		return
	}
	goName := publicName(name, makePublic)
	// Check if already generated
	if generated[goName] {
		return
	}
	generated[goName] = true

	// Determine target namespace for XMLName
	ns := schema.TargetNamespace
	if ns == "" {
		ns = ""
	}

	// If element has type attribute
	if el.Type != "" {
		goType := xsdTypeToGo(el.Type, el.Nillable == "true", el.MaxOccurs)
		// Need to handle pointer/slice for this element as top-level type alias
		// For top-level element with type, generate alias: type GoName GoType
		// But need to handle special cases: if GoType is string and element is enumeration? That's simpleType case, not this.
		// Also need to handle if GoType is like "string" and el.Type is s:string, then alias is string
		// For s:dateTime etc., need to generate alias with methods
		// Check if goType is soap type like soap.XSDDateTime, then generate alias with Marshal methods
		if goType == "soap.XSDDateTime" || goType == "soap.XSDDate" || goType == "soap.XSDTime" {
			// Generate alias with methods
			fmt.Fprintf(buf, "type %s %s\n\n", goName, goType)
			if makePublic {
				// Only generate methods if makePublic? In test.wsdl, StartDate with makePublic false still had methods but with lower name
				// For false, type is startDate, and methods receiver is (xdt startDate)
				fmt.Fprintf(buf, "func (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n", goName)
				buf.WriteString("\treturn soap.XSDDateTime(xdt).MarshalXML(e, start)\n")
				buf.WriteString("}\n\n")
				fmt.Fprintf(buf, "func (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n", goName)
				buf.WriteString("\treturn (*soap.XSDDateTime)(xdt).UnmarshalXML(d, start)\n")
				buf.WriteString("}\n\n")
			} else {
				fmt.Fprintf(buf, "func (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n", goName)
				buf.WriteString("\treturn soap.XSDDateTime(xdt).MarshalXML(e, start)\n")
				buf.WriteString("}\n\n")
				fmt.Fprintf(buf, "func (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n", goName)
				buf.WriteString("\treturn (*soap.XSDDateTime)(xdt).UnmarshalXML(d, start)\n")
				buf.WriteString("}\n\n")
			}
			return
		}
		// Handle slice and pointer for top-level element alias? In our earlier test, element MyString with type s:string gave "type MyString string" not slice
		// For element with maxOccurs unbounded at top-level? Top-level element maxOccurs not relevant
		// So just alias
		// Need to handle if goType already includes pointer/slice? Our xsdTypeToGo returns base, but for top-level we should not wrap with pointer/slice based on el's attributes? Top-level element's minOccurs/maxOccurs not used (it's global)
		// For alias, just use base
		// But need to handle prefix pointer types like *Duration etc.
		// For duration etc., we saw *Duration even for top-level? But for top-level element with s:duration, we got *Duration? Let's see: we had MyString with s:duration gave type? Actually we tested duration with TestType, not top-level element alias
		// For top-level element with type s:duration, what would it generate? Let's not worry: just generate alias with base type, but if isPointerType, add *
		local := el.Type
		if idx := strings.LastIndex(local, ":"); idx != -1 {
			local = local[idx+1:]
		}
		if isPointerType(local) {
			goType = "*" + xsdTypeToGo(el.Type, false, "")
			// But we already have goType as base without star, so adjust
			// Actually xsdTypeToGo for duration returns "Duration" (without star), but we need "*Duration"
			// So we should handle isPointerType here
			if !strings.HasPrefix(goType, "*") && !strings.HasPrefix(goType, "[]") {
				goType = "*" + goType
			}
		}
		// For custom types, goType is like "MyType", but we need to ensure it's capitalized per makePublic
		// But alias target should keep original case? For type alias, if makePublic false, should lower?
		// In test.wsdl, ResponseStatus's attribute code had type with enumeration but not alias
		// For now, keep as is
		fmt.Fprintf(buf, "type %s %s\n\n", goName, goType)
		return
	}
	// If element has inline complexType
	if el.ComplexType != nil {
		ct := el.ComplexType
		// Generate struct with XMLName
		fmt.Fprintf(buf, "type %s struct {\n", goName)
		fmt.Fprintf(buf, "\tXMLName xml.Name `xml:\"%s %s\"`\n\n", ns, name)
		// Process documentation if any
		if ct.Annotation != nil && len(ct.Annotation.Documentation) > 0 {
			for _, doc := range ct.Annotation.Documentation {
				text := strings.TrimSpace(doc.Value)
				if text != "" {
					for _, line := range strings.Split(text, "\n") {
						fmt.Fprintf(buf, "\t// %s\n\n", strings.TrimSpace(line))
					}
				}
			}
		}
		// Generate fields from complexType's sequence/choice/all/attributes etc.
		generateFields(buf, ct, schema, makePublic, 1)
		buf.WriteString("}\n\n")
		return
	}
	if el.SimpleType != nil {
		st := el.SimpleType
		// If simpleType has restriction with enumerations, generate string alias with constants
		if st.Restriction != nil {
			base := st.Restriction.Base
			goBase := xsdTypeToGo(base, false, "")
			// Determine if base is string -> alias string, else maybe other
			if goBase == "string" || goBase == "AnyURI" || goBase == "NCName" {
				// Generate type alias
				fmt.Fprintf(buf, "type %s string\n\n", goName)
				if len(st.Restriction.Enumerations) > 0 {
					buf.WriteString("const (\n")
					for _, enum := range st.Restriction.Enumerations {
						// Enum value
						val := enum.Value
						// Constant name: GoName + EnumValue (capitalized, sanitize)
						// For test, enum values are enum1, enum2, and constants are ElementWithLocalSimpleTypeEnum1 etc.
						// Sanitized: remove non-alphanumeric, capitalize
						constName := goName + sanitizeEnum(val)
						// For makePublic false, lower first of constName?
						if !makePublic {
							constName = lowerFirst(constName)
						}
						// Documentation for enum
						if enum.Annotation != nil && len(enum.Annotation.Documentation) > 0 {
							for _, doc := range enum.Annotation.Documentation {
								text := strings.TrimSpace(doc.Value)
								if text != "" {
									fmt.Fprintf(buf, "\n\t// %s\n", text)
								}
							}
						}
						fmt.Fprintf(buf, "\t%s %s = \"%s\"\n\n", constName, goName, val)
					}
					buf.WriteString(")\n\n")
				}
				return
			} else {
				// SimpleType with other base, maybe just alias
				fmt.Fprintf(buf, "type %s %s\n\n", goName, goBase)
				return
			}
		}
		// Other simpleType cases like list/union
		fmt.Fprintf(buf, "type %s string\n\n", goName)
		return
	}
	// Fallback: empty struct
	fmt.Fprintf(buf, "type %s struct {\n", goName)
	fmt.Fprintf(buf, "\tXMLName xml.Name `xml:\"%s %s\"`\n", ns, name)
	buf.WriteString("}\n\n")
}

func generateComplexType(buf *bytes.Buffer, ct *XSDComplexType, schema *XSDSchema, makePublic bool, generated map[string]bool, schemas []*XSDSchema) {
