func generateServer(path string, wsdl *WSDL, schemas []*XSDSchema, pkg string, makePublic bool, rawWsdl []byte) error {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	buf.WriteString(fmt.Sprintf("package %s\n\n", pkg))
	buf.WriteString("import (\n")
	buf.WriteString("\t\"encoding/xml\"\n")
	buf.WriteString("\t\"errors\"\n")
	buf.WriteString("\t\"fmt\"\n")
	buf.WriteString("\t\"net/http\"\n")
	buf.WriteString("\t\"reflect\"\n")
	buf.WriteString("\t\"strings\"\n")
	buf.WriteString(")\n\n")
	// wsdl var with raw content
	// Need to escape backticks? Raw string with backticks cannot contain backticks. WSDL content doesn't contain backticks, so safe.
	// Use raw string literal: var wsdl = `...`
	// Ensure we keep exactly as file content
	wsdlStr := string(rawWsdl)
	// The wsdl var in original uses ` (backtick) without extra newline? For test, it was "var wsdl = `<?xml ..." with no leading newline
	buf.WriteString("var wsdl = `")
	buf.WriteString(wsdlStr)
	buf.WriteString("`\n\n")
	buf.WriteString("var WSDLUndefinedError = errors.New(\"Server was unable to process request. --> Object reference not set to an instance of an object.\")\n\n")

	// Determine operations for server: same as client but we need request/response element names for SOAPBody
	// For server, we need to collect all operations across all portTypes
	type ServerOp struct {
		FieldName string // request element name
		RequestType string
		ResponseType string
	}
	var serverOps []ServerOp
	seenFields := make(map[string]bool)
	for _, pt := range wsdl.PortTypes {
		for _, op := range pt.Operations {
			if op.Input == nil || op.Output == nil {
				continue
			}
			// Get request element name
			var reqEl, respEl string
			var reqType, respType string
			// Input message
			msgName := op.Input.Message
			localMsg := msgName
			if idx := strings.LastIndex(msgName, ":"); idx != -1 {
				localMsg = msgName[idx+1:]
			}
			for _, msg := range wsdl.Messages {
				if msg.Name == localMsg {
					if len(msg.Parts) > 0 {
						part := msg.Parts[0]
						if part.Element != "" {
							el := part.Element
							if idx := strings.LastIndex(el, ":"); idx != -1 {
								el = el[idx+1:]
							}
							reqEl = el
							reqType = publicName(el, true)
						} else if part.Type != "" {
							t := part.Type
							if idx := strings.LastIndex(t, ":"); idx != -1 {
								t = t[idx+1:]
							}
							reqEl = t
							reqType = publicName(t, true)
						}
					}
					break
				}
			}
			// Output
			msgName = op.Output.Message
			localMsg = msgName
			if idx := strings.LastIndex(msgName, ":"); idx != -1 {
				localMsg = msgName[idx+1:]
			}
			for _, msg := range wsdl.Messages {
				if msg.Name == localMsg {
					if len(msg.Parts) > 0 {
						part := msg.Parts[0]
						if part.Element != "" {
							el := part.Element
							if idx := strings.LastIndex(el, ":"); idx != -1 {
								el = el[idx+1:]
							}
							respEl = el
							respType = publicName(el, true)
							_ = respEl
						} else if part.Type != "" {
							t := part.Type
							if idx := strings.LastIndex(t, ":"); idx != -1 {
								t = t[idx+1:]
							}
							respType = publicName(t, true)
						}
					}
					break
				}
			}
			if reqEl == "" || reqType == "" || respType == "" {
				continue
			}
			fieldName := publicName(reqEl, true)
			// For server, field name is request element name (capitalized)
			// Avoid duplicates
			key := fieldName + ":" + reqType + ":" + respType
			if seenFields[key] {
				continue
			}
			seenFields[key] = true
			serverOps = append(serverOps, ServerOp{FieldName: fieldName, RequestType: reqType, ResponseType: respType})
		}
	}

	buf.WriteString("type SOAPEnvelopeRequest struct {\n")
	buf.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Envelope\"`\n")
	buf.WriteString("\tBody    SOAPBodyRequest\n")
	buf.WriteString("}\n\n")

	buf.WriteString("type SOAPBodyRequest struct {\n")
	buf.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n\n")
	for _, op := range serverOps {
		fmt.Fprintf(&buf, "\t%s *%s `xml:\",omitempty\"`\n", op.FieldName, op.RequestType)
	}
	if len(serverOps) == 0 {
		// Still need blank line
	}
	buf.WriteString("}\n\n")

	buf.WriteString("type SOAPEnvelopeResponse struct {\n")
	buf.WriteString("\tXMLName    xml.Name `xml:\"soap:Envelope\"`\n")
	buf.WriteString("\tPrefixSoap string   `xml:\"xmlns:soap,attr\"`\n")
	buf.WriteString("\tPrefixXsi  string   `xml:\"xmlns:xsi,attr\"`\n")
	buf.WriteString("\tPrefixXsd  string   `xml:\"xmlns:xsd,attr\"`\n\n")
	buf.WriteString("\tBody SOAPBodyResponse\n")
	buf.WriteString("}\n\n")

	buf.WriteString("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n")
	buf.WriteString("\treturn &SOAPEnvelopeResponse{\n")
	buf.WriteString("\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n")
	buf.WriteString("\t\tPrefixXsd:  \"http://www.w3.org/2001/XMLSchema\",\n")
	buf.WriteString("\t\tPrefixXsi:  \"http://www.w3.org/2001/XMLSchema-instance\",\n")
	buf.WriteString("\t}\n")
	buf.WriteString("}\n\n")

	buf.WriteString("type Fault struct {\n")
	buf.WriteString("\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n")
	buf.WriteString("\tSpace   string   `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n")
	buf.WriteString("\tCode   string `xml:\"faultcode,omitempty\"`\n")
	buf.WriteString("\tString string `xml:\"faultstring,omitempty\"`\n")
	buf.WriteString("\tActor  string `xml:\"faultactor,omitempty\"`\n")
	buf.WriteString("\tDetail string `xml:\"detail,omitempty\"`\n")
	buf.WriteString("}\n\n")

	buf.WriteString("type SOAPBodyResponse struct {\n")
	buf.WriteString("\tXMLName xml.Name `xml:\"soap:Body\"`\n")
	buf.WriteString("\tFault   *Fault   `xml:\",omitempty\"`\n\n")
	for _, op := range serverOps {
		fmt.Fprintf(&buf, "\t%s *%s `xml:\",omitempty\"`\n", op.FieldName, op.ResponseType)
	}
	buf.WriteString("}\n\n")

	for _, op := range serverOps {
		fmt.Fprintf(&buf, "func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n", op.FieldName, op.RequestType, op.ResponseType)
		buf.WriteString("\treturn nil, WSDLUndefinedError\n")
		buf.WriteString("}\n\n")
	}

	buf.WriteString("func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {\n")
	buf.WriteString("\tw.Header().Add(\"Content-Type\", \"text/xml; charset=utf-8\")\n")
	buf.WriteString("\tval := reflect.ValueOf(&service.Body).Elem()\n")
	buf.WriteString("\tn := val.NumField()\n")
	buf.WriteString("\tvar field reflect.Value\n")
	buf.WriteString("\tvar name string\n")
	buf.WriteString("\tfind := false\n\n")
	buf.WriteString("\tif r.Method == http.MethodGet {\n")
	buf.WriteString("\t\tw.Write([]byte(wsdl))\n")
	buf.WriteString("\t\treturn\n")
	buf.WriteString("\t}\n\n")
	buf.WriteString("\tresp := NewSOAPEnvelopResponse()\n")
	buf.WriteString("\tdefer func() {\n")
	buf.WriteString("\t\tif r := recover(); r != nil {\n")
	buf.WriteString("\t\t\tresp.Body.Fault = &Fault{}\n")
	buf.WriteString("\t\t\tresp.Body.Fault.Space = \"http://schemas.xmlsoap.org/soap/envelope/\"\n")
	buf.WriteString("\t\t\tresp.Body.Fault.Code = \"soap:Server\"\n")
	buf.WriteString("\t\t\tresp.Body.Fault.Detail = fmt.Sprintf(\"%v\", r)\n")
	buf.WriteString("\t\t\tresp.Body.Fault.String = fmt.Sprintf(\"%v\", r)\n")
	buf.WriteString("\t\t}\n")
	buf.WriteString("\t\txml.NewEncoder(w).Encode(resp)\n")
	buf.WriteString("\t}()\n\n")
	buf.WriteString("\theader := r.Header.Get(\"Content-Type\")\n")
	buf.WriteString("\tif strings.Index(header, \"application/soap+xml\") >= 0 {\n")
	buf.WriteString("\t\tpanic(\"Could not find an appropriate Transport Binding to invoke.\")\n")
	buf.WriteString("\t}\n\n")
	buf.WriteString("\terr := xml.NewDecoder(r.Body).Decode(service)\n")
	buf.WriteString("\tif err != nil {\n")
	buf.WriteString("\t\tpanic(err)\n")
	buf.WriteString("\t}\n\n")
	buf.WriteString("\tfor i := 0; i < n; i++ {\n")
	buf.WriteString("\t\tfield = val.Field(i)\n")
	buf.WriteString("\t\tname = val.Type().Field(i).Name\n")
	buf.WriteString("\t\tif field.Kind() != reflect.Ptr {\n")
	buf.WriteString("\t\t\tcontinue\n")
	buf.WriteString("\t\t}\n")
	buf.WriteString("\t\tif field.IsNil() {\n")
	buf.WriteString("\t\t\tcontinue\n")
	buf.WriteString("\t\t}\n")
	buf.WriteString("\t\tif field.IsValid() {\n")
	buf.WriteString("\t\t\tfind = true\n")
	buf.WriteString("\t\t\tbreak\n")
	buf.WriteString("\t\t}\n")
	buf.WriteString("\t}\n\n")
	buf.WriteString("\tif !find {\n")
	buf.WriteString("\t\tpanic(WSDLUndefinedError)\n")
	buf.WriteString("\t} else {\n")
	buf.WriteString("\t\tm := val.Addr().MethodByName(name + \"Func\")\n")
	buf.WriteString("\t\tif !m.IsValid() {\n")
	buf.WriteString("\t\t\tpanic(WSDLUndefinedError)\n")
	buf.WriteString("\t\t}\n\n")
	buf.WriteString("\t\tvals := m.Call([]reflect.Value{field})\n")
	buf.WriteString("\t\tif vals[1].IsNil() {\n")
	buf.WriteString("\t\t\treflect.ValueOf(&resp.Body).Elem().FieldByName(name).Set(vals[0])\n")
	buf.WriteString("\t\t} else {\n")
	buf.WriteString("\t\t\tpanic(vals[1].Interface())\n")
	buf.WriteString("\t\t}\n")
	buf.WriteString("\t}\n\n")
	buf.WriteString("}\n\n")

	buf.WriteString("func Endpoint(w http.ResponseWriter, r *http.Request) {\n")
	buf.WriteString("\trequest := SOAPEnvelopeRequest{}\n")
	buf.WriteString("\trequest.call(w, r)\n")
	buf.WriteString("}\n")

	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		// Write unformatted and return error to be printed
		if e := os.WriteFile(path, buf.Bytes(), 0644); e != nil {
			return e
		}
		return fmt.Errorf("%v", err)
	}
	if err := os.WriteFile(path, formatted, 0644); err != nil {
		return err
	}
	return nil
}
